    def fmt(p):
        return f"{len(p)}\n" + ' '.join(map(str, p))

    tests = [fmt([0]), fmt([13]), fmt([1, 1, 1, 1, 1]), fmt([10**9]), fmt([0, 0, 0]), fmt([5, 0, 5, 0]), fmt([10**9, 0, 10**9, 1])]
    for n in (2, 3, 4, 6, 10, 15):
        for vmax in (7, 10**9):
            tests.append(fmt([rng.randint(0, vmax) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n)]))
    tests.append(fmt([10**9] * n))
    tests.append(fmt([rng.randint(0, 3) for _ in range(n)]))
    tests.append(fmt([i for i in range(n)]))
    return tests

